#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    long double probability = 1.0L / n;
    const long double total = (long double)n * m;
    const long double notOne = (long double)n * (m - 1);

    for (long long k = 0; k < m - 1; ++k) {
        probability *= (notOne - k) / (total - 1 - k);
    }

    long double weight = n * probability;
    long double answer = 0.0L;

    for (long long j = 1; j <= n; ++j) {
        long double ratio = (long double)j / n;
        answer += ratio * ratio * weight;

        if (j >= m) {
            weight = 0.0L;
        } else {
            long double denominator =
                (long double)n * (m - 1) - m + j + 1;
            weight *= (long double)(n - j) / (j + 1);
            weight *= (long double)(m - j) / denominator;
        }
    }

    cout << fixed << setprecision(10)
         << (long double)n * answer << '\n';

    return 0;
}

