#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    const long double N = n;
    const long double M = m;
    const long double B = N * (M - 1.0L);

    const long double logDenominator =
        lgammal(N * M + 1.0L) - lgammal(N * M - M + 1.0L);

    long double p = 0.0L;

    for (long long j = 1; j <= n && j <= m; ++j) {
        const long long remaining = m - j;
        if (B < static_cast<long double>(remaining))
            continue;

        const long double logCombination =
            lgammal(N + 1.0L) - lgammal(j + 1.0L) -
            lgammal(N - j + 1.0L);

        const long double logProbability =
            lgammal(M + 1.0L) - lgammal(M - j + 1.0L) +
            lgammal(B + 1.0L) - lgammal(B - remaining + 1.0L) -
            logDenominator;

        const long double ratio = static_cast<long double>(j) / N;
        p += expl(logCombination + logProbability) * ratio * ratio;
    }

    cout << fixed << setprecision(10) << N * p << '\n';
    return 0;
}

