int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    const long double total = static_cast<long double>(n) * m;
    long double probability = static_cast<long double>(m) / total;
    const long double notJ = static_cast<long double>(n) * (m - 1);

    for (long long k = 0; k < m - 1; ++k) {
        probability *= (notJ - k) / (total - 1 - k);
    }

    long double weightedProbability = n * probability;
    long double answer = 0;
    const long long limit = min(n, m);

    for (long long j = 1; j <= limit; ++j) {
        long double ratio = static_cast<long double>(j) / n;
        answer += weightedProbability * ratio * ratio;

        if (j < limit) {
            weightedProbability *=
                (static_cast<long double>(n - j) / (j + 1)) *
                (static_cast<long double>(m - j) /
                 (total - n - m + j + 1));
        }
    }

    cout << fixed << setprecision(10) << static_cast<long double>(n) * answer << '\n';
    return 0;
}

