int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    if (n <= 0 || m <= 0) {
        cout << fixed << setprecision(10) << 0.0 << '\n';
        return 0;
    }

    const long long limit = min(n, m);
    const long double total = static_cast<long double>(n) * m;
    const long double other = static_cast<long double>(n) * (m - 1);

    long double probability = static_cast<long double>(m) / total;
    for (long long k = 0; k < m - 1; ++k) {
        probability *= (other - k) / (total - k - 1);
    }

    long double weightedProbability = n * probability;
    long double answer = 0.0L;

    for (long long j = 1; j <= limit; ++j) {
        const long double ratio = static_cast<long double>(j) / n;
        answer += weightedProbability * ratio * ratio;

        if (j < limit) {
            weightedProbability *=
                (static_cast<long double>(n - j) / (j + 1)) *
                (static_cast<long double>(m - j) /
                 (other - m + j + 1));
        }
    }

    cout << fixed << setprecision(10)
         << static_cast<long double>(n) * answer << '\n';

    return 0;
}

